mapper.select:
SELECT r.id, r.name, r.description, r.created_by AS createdBy, r.created_date AS createdDate, r.updated_by AS updatedBy, r.updated_date AS updatedDate FROM roles r WHERE r.deleted = false
AND (r.name ILIKE '%' || #{keyword} || '%' OR r.description ILIKE '%' || #{keyword} || '%')
ORDER BY r.created_date DESC LIMIT #{limit} OFFSET #{offset}
